import torch
from torch import Tensor

c = 1.0

def u(t: Tensor, x: Tensor, y: Tensor, z: Tensor) -> Tensor:
	r_sq = x**2+y**2+z**2

	E_x = 4.00000*torch.exp(-(10.*(r_sq)**(1/2)-10.*t-3.)**2)*((1.000000000*y**5+(2.000000000*x**2+2.000000000*z**2+(t+.3000000000)**2)*y**3+(-.6000000000-2.000000000*t)*z*x*y**2+(1.000000000*x**4+(2.000000000*z**2+(t+.3000000000)**2)*x**2+1.000000000*z**4+(t+.3000000000)**2*z**2)*y+(-.6000000000-2.000000000*t)*z*x**3+((-.6000000000-2.000000000*t)*z**3+(-.1500000000e-1*t-.4500000000e-2)*z)*x)*(r_sq)**(1/2)+(-.6000000000-2.000000000*t)*y**5+1.000000000*x*y**4*z+((-1.200000000-4.000000000*t)*x**2+(-1.200000000-4.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*y**3+(2.000000000*x**3*z+(2.000000000*z**3+(1.000000000*t**2+.6000000000*t+.1000000000)*z)*x)*y**2+((-.6000000000-2.000000000*t)*x**4+((-1.200000000-4.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*x**2+(-.6000000000-2.000000000*t)*z**4+(-.5000000000e-2*t-.1500000000e-2)*z**2)*y+1.000000000*x**5*z+(2.000000000*z**3+(1.000000000*t**2+.6000000000*t+.1000000000)*z)*x**3+(1.000000000*z**5+(1.000000000*t**2+.6000000000*t+.1000000000)*z**3+.7500000000e-4*z)*x)/(r_sq)**(5/2)
	E_y =  -4.00000*torch.exp(-(10.*(r_sq)**(1/2)-10.*t-3.)**2)*((1.000000000*x**5+(2.000000000*y**2+2.000000000*z**2+(t+.3000000000)**2)*x**3+(2.000000000*t+.6000000000)*z*y*x**2+(1.000000000*y**4+(2.000000000*z**2+(t+.3000000000)**2)*y**2+1.000000000*z**4+(t+.3000000000)**2*z**2)*x+(2.000000000*t+.6000000000)*z*y**3+((2.000000000*t+.6000000000)*z**3+(.4500000000e-2+.1500000000e-1*t)*z)*y)*(r_sq)**(1/2)+(-.6000000000-2.000000000*t)*x**5-1.000000000*x**4*y*z+((-1.200000000-4.000000000*t)*y**2+(-1.200000000-4.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*x**3+(-2.000000000*y**3*z+(-2.000000000*z**3+(-.1000000000-1.000000000*t**2-.6000000000*t)*z)*y)*x**2+((-.6000000000-2.000000000*t)*y**4+((-1.200000000-4.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*y**2+(-.6000000000-2.000000000*t)*z**4+(-.5000000000e-2*t-.1500000000e-2)*z**2)*x-1.000000000*y**5*z+(-2.000000000*z**3+(-.1000000000-1.000000000*t**2-.6000000000*t)*z)*y**3+(-1.000000000*z**5+(-.1000000000-1.000000000*t**2-.6000000000*t)*z**3-.7500000000e-4*z)*y)/(r_sq)**(5/2)
	E_z =  -4.00000*torch.exp(-(10.*(r_sq)**(1/2)-10.*t-3.)**2)*(((-.6000000000-2.000000000*t)*x**4+((-1.200000000-4.000000000*t)*y**2+(-.6000000000-2.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*x**2+(-.6000000000-2.000000000*t)*y**4+((-.6000000000-2.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*y**2+(.3000000000e-2+.1000000000e-1*t)*z**2)*(r_sq)**(1/2)+1.000000000*x**6+(3.000000000*y**2+2.000000000*z**2+(t+.3000000000)**2)*x**4+(3.000000000*y**4+(4.000000000*z**2+2.000000000*(t+.3000000000)**2)*y**2+.2500000000e-4+1.000000000*z**4+(t+.4000000000)*(t+.2000000000)*z**2)*x**2+1.000000000*y**6+(2.000000000*z**2+(t+.3000000000)**2)*y**4+(.2500000000e-4+1.000000000*z**4+(t+.4000000000)*(t+.2000000000)*z**2)*y**2-.5000000000e-4*z**2-.1000000000e-1*z**4)/(r_sq)**(5/2)
	B_x =  4.00000*torch.exp(-(10.*(r_sq)**(1/2)-10.*t-3.)**2)/(r_sq)**(5/2)*((-1.000000000*y**5+(-2.000000000*x**2-2.000000000*z**2-(t+.3000000000)**2)*y**3+(-.6000000000-2.000000000*t)*z*x*y**2+(-1.000000000*x**4+(-2.000000000*z**2-(t+.3000000000)**2)*x**2-1.000000000*z**4-(t+.3000000000)**2*z**2)*y+(-.6000000000-2.000000000*t)*z*x**3+((-.6000000000-2.000000000*t)*z**3+(-.1500000000e-1*t-.4500000000e-2)*z)*x)*(r_sq)**(1/2)+(2.000000000*t+.6000000000)*y**5+1.000000000*x*y**4*z+((1.200000000+4.000000000*t)*x**2+(1.200000000+4.000000000*t)*z**2+.5000000000e-2*t+.1500000000e-2)*y**3+(2.000000000*x**3*z+(2.000000000*z**3+(1.000000000*t**2+.6000000000*t+.1000000000)*z)*x)*y**2+((2.000000000*t+.6000000000)*x**4+((1.200000000+4.000000000*t)*z**2+.5000000000e-2*t+.1500000000e-2)*x**2+(2.000000000*t+.6000000000)*z**4+(.5000000000e-2*t+.1500000000e-2)*z**2)*y+1.000000000*x**5*z+(2.000000000*z**3+(1.000000000*t**2+.6000000000*t+.1000000000)*z)*x**3+(1.000000000*z**5+(1.000000000*t**2+.6000000000*t+.1000000000)*z**3+.7500000000e-4*z)*x)
	B_y =  4.00000*torch.exp(-(10.*(r_sq)**(1/2)-10.*t-3.)**2)*((1.000000000*x**5+(2.000000000*y**2+2.000000000*z**2+(t+.3000000000)**2)*x**3+(-.6000000000-2.000000000*t)*z*y*x**2+(1.000000000*y**4+(2.000000000*z**2+(t+.3000000000)**2)*y**2+1.000000000*z**4+(t+.3000000000)**2*z**2)*x+(-.6000000000-2.000000000*t)*z*y**3+((-.6000000000-2.000000000*t)*z**3+(-.1500000000e-1*t-.4500000000e-2)*z)*y)*(r_sq)**(1/2)+(-.6000000000-2.000000000*t)*x**5+1.000000000*x**4*y*z+((-1.200000000-4.000000000*t)*y**2+(-1.200000000-4.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*x**3+(2.000000000*y**3*z+(2.000000000*z**3+(1.000000000*t**2+.6000000000*t+.1000000000)*z)*y)*x**2+((-.6000000000-2.000000000*t)*y**4+((-1.200000000-4.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*y**2+(-.6000000000-2.000000000*t)*z**4+(-.5000000000e-2*t-.1500000000e-2)*z**2)*x+1.000000000*y**5*z+(2.000000000*z**3+(1.000000000*t**2+.6000000000*t+.1000000000)*z)*y**3+(1.000000000*z**5+(1.000000000*t**2+.6000000000*t+.1000000000)*z**3+.7500000000e-4*z)*y)/(r_sq)**(5/2)
	B_z =  -4.00000*torch.exp(-(10.*(r_sq)**(1/2)-10.*t-3.)**2)*(((-.6000000000-2.000000000*t)*x**4+((-1.200000000-4.000000000*t)*y**2+(-.6000000000-2.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*x**2+(-.6000000000-2.000000000*t)*y**4+((-.6000000000-2.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*y**2+(.3000000000e-2+.1000000000e-1*t)*z**2)*(r_sq)**(1/2)+1.000000000*x**6+(3.000000000*y**2+2.000000000*z**2+(t+.3000000000)**2)*x**4+(3.000000000*y**4+(4.000000000*z**2+2.000000000*(t+.3000000000)**2)*y**2+.2500000000e-4+1.000000000*z**4+(t+.4000000000)*(t+.2000000000)*z**2)*x**2+1.000000000*y**6+(2.000000000*z**2+(t+.3000000000)**2)*y**4+(.2500000000e-4+1.000000000*z**4+(t+.4000000000)*(t+.2000000000)*z**2)*y**2-.5000000000e-4*z**2-.1000000000e-1*z**4)/(r_sq)**(5/2)

	return torch.vstack((E_x, E_y, E_z, B_x, B_y, B_z))